"""Derive SkyyZones/build_skyyzones_0.2.1.py from SkyyZones/build_skyyzones_0.2.0.py (the tools/deploy_set.py SET pin; generated by
tools/zones_0_2_0_patch.py - never re-run that one). Edit THIS patch, never the generated script. Every anchor is asserted; at the end
every change is undone on a copy and compared with 0.2.0 (tools/soundpass_gen.Patch). Line endings kept.
Run:  python tools/zones_0_2_1_patch.py   then   python SkyyZones/build_skyyzones_0.2.1.py   (never --deploy)
Harness: python SkyyZones/test_skyyzones_0.2.1.py [--keep]

0.2.1 = round wg0710 (research/Zone-Reset-Spec.md 3.4-A + 10; SkyyWorldGen 0.7.10 /zone <n> reset + undo). Skyy 2026-10-23: "ive explored
 most of zone 1 already. make a new zone 1 with the new structures." / "maybe add a command i can do in game. like /zone 1 reset" / "but if
 you can, also add an undo incase someone does it by accident."
 TWO NEW BRIDGE FUNCTIONS (class ZBox, java.lang / java.util.function types only), called by SkyyWorldGen on the reset zone's world thread:
  zones:fn:dropBox    Object[] { String world, java.util.function.IntBinaryOperator owner(chunkX, chunkZ) -> 1 = in the reset zone[,
                      String spool file (fix round 2: every line is appended there, synced, BEFORE anything is dropped)] }
                      -> String: every waiting regrow block (D line) and every grown-back spot still checked after a start (V line) of
                      that world whose chunk the owner names - REMOVED without putting the block back (the land is regenerated), one R
                      journal line per waiting block, then a fresh snapshot. The returned lines (the snapshot's own format) go into
                      SkyyWorldGen's reset backup. null = bad arguments. Must run BEFORE the zone's chunks are regenerated, or a regrow
                      would write an old ore into the new land.
  zones:fn:restoreBox Object[] { String world, String lines } -> Integer: the undo - every D line put back as a waiting block (journal D
                      line first; one already waiting at that spot is kept), every V line back on the check list; then a snapshot.
                      -1 = no regen folder yet. The restored blocks grow back on their old timers (most are already due: they come back
                      at the first pass once their chunk is loaded - exactly as after a restart).
 Regions (regions.properties) are NOT touched (admin boxes, not land - SkyyWorldGen's reset summary lists the regions in the zone).
 Saved data: no format change (the same journal / snapshot lines). Config: none. No new command / system / event.
 ROLLBACK to 0.2.0: safe (the files stay readable); SkyyWorldGen 0.7.10's reset then skips the regrow step with a WARN - roll SkyyWorldGen
 0.7.10 + SkyyZones 0.2.1 + SkyyExploration 0.3.4 back together (tools/deploy_set.py FLOOR wg0710).
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G

P = G.Patch(os.path.join(ROOT, "SkyyZones", "build_skyyzones_0.2.0.py"), os.path.join(ROOT, "SkyyZones", "build_skyyzones_0.2.1.py"))
assert P.has('VERSION = "0.2.0"\n') and P.has("tools/zones_0_2_0_patch.py") and not P.has("ZBox"), "not the generated SkyyZones 0.2.0"
SYS0, CMD0 = P.s.count("registerSystem("), P.s.count("registerCommand(")

P.rep('''"""SkyyZones 0.2.0 - build script (derived from the hand-written 0.1.0 by tools/zones_0_2_0_patch.py - edit the patch, not this file).
''', '''"""SkyyZones 0.2.1 - build script. GENERATED by tools/zones_0_2_1_patch.py from build_skyyzones_0.2.0.py (itself derived from the
hand-written 0.1.0 by tools/zones_0_2_0_patch.py) - edit the patch, not this file.
Run: python SkyyZones/build_skyyzones_0.2.1.py -> SkyyZones/SkyyZones-0.2.1.jar; harness: python SkyyZones/test_skyyzones_0.2.1.py
NEW IN 0.2.1 (round wg0710, SkyyWorldGen 0.7.10 /zone <n> reset + undo; details + ROLLBACK: tools/zones_0_2_1_patch.py): the bridge
functions zones:fn:dropBox (a reset zone's waiting regrow blocks are forgotten WITHOUT putting them back, R journal lines, the dropped lines
returned for the reset backup) and zones:fn:restoreBox (the undo puts them back).
''')
P.rep('VERSION = "0.2.0"\n', 'VERSION = "0.2.1"\n')

# ---- ZBox: the two reset bridge functions (before ZFn: publish() names it)
P.rep('''# =====================================================================================================================================
# ZFn: the bridge functions
# =====================================================================================================================================
''', r'''# =====================================================================================================================================
# 0.2.1 ZBox: zones:fn:dropBox / zones:fn:restoreBox (SkyyWorldGen 0.7.10's /zone <n> reset + undo; the reset zone's world thread)
# =====================================================================================================================================
bx = mk("ZBox", None, ("java.util.function.Function",))
F(bx, "public int mode;")
F(bx, "public static volatile @PKG@.ZBox DROP = null;")
F(bx, "public static volatile @PKG@.ZBox BACK = null;")
F(bx, "public static final java.util.concurrent.atomic.AtomicLong DROPPED = new java.util.concurrent.atomic.AtomicLong();")
F(bx, "public static final java.util.concurrent.atomic.AtomicLong RESTORED = new java.util.concurrent.atomic.AtomicLong();")
C(bx, "public ZBox(int mode) { this.mode = mode; }")
M(bx, r"""
public static boolean owned(java.util.function.IntBinaryOperator f, int x, int z) {
  return f.applyAsInt(x >> 5, z >> 5) != 0;
}""")
# the waiting blocks (D) + the grown-back spots still checked / kept (V) in the owner's chunks: out of memory without a block write, an R
# journal line per waiting block, then a fresh snapshot (an unreadable-at-start world keeps its files: the R lines still say it)
M(bx, r"""
public static boolean spool(String sp, String s) {
  if (sp == null || sp.length() == 0 || s == null || s.length() == 0) return true;
  try {
    java.nio.file.Path f = new java.io.File(sp).toPath();
    java.nio.file.Files.createDirectories(f.getParent(), new java.nio.file.attribute.FileAttribute[0]);
    java.nio.file.Files.write(f, s.getBytes("UTF-8"), new java.nio.file.OpenOption[] { java.nio.file.StandardOpenOption.CREATE, java.nio.file.StandardOpenOption.APPEND, java.nio.file.StandardOpenOption.DSYNC });
    return true;
  } catch (Throwable t) { @PKG@.ZCfg.warnOnce("zboxspool", "zone reset: could not write the spool " + sp + ": " + t); return false; }
}""")
# fix round 2 (critic: a crash inside the drop lost the rows): every line is READ first and spooled (sp, a file in SkyyWorldGen's reset
# backup, synced) BEFORE anything is dropped - a crash part way leaves them for SkyyWorldGen's next start; no spool -> nothing dropped
M(bx, r"""
public static String drop(String w, java.util.function.IntBinaryOperator f, String sp) {
  @PKG@.ZRw r = @PKG@.ZRegen.rw(w, false);
  if (r == null) return "";
  java.util.ArrayList ds = new java.util.ArrayList();
  java.util.ArrayList cs = new java.util.ArrayList();
  java.util.ArrayList rs = new java.util.ArrayList();
  StringBuilder all = new StringBuilder();
  java.util.Iterator it = r.dep.values().iterator();
  while (it.hasNext()) {
    @PKG@.ZDep d = (@PKG@.ZDep) it.next();
    if (!owned(f, d.x, d.z)) continue;
    ds.add(new Object[] { d, d.line() });
    all.append(d.line()).append('\n');
  }
  java.util.Iterator ci = r.check.values().iterator();
  while (ci.hasNext()) {
    @PKG@.ZDep v = (@PKG@.ZDep) ci.next();
    if (!owned(f, v.x, v.z)) continue;
    cs.add(v);
    all.append(v.vline()).append('\n');
  }
  java.util.Iterator ri = r.recent.values().iterator();
  while (ri.hasNext()) {
    @PKG@.ZDep v = (@PKG@.ZDep) ri.next();
    if (!owned(f, v.x, v.z)) continue;
    rs.add(v);
    all.append(v.vline()).append('\n');
  }
  if (!spool(sp, all.toString())) return "#ERROR the regrow rows could not be saved into the reset backup first (" + sp + ") - nothing was dropped\n";
  StringBuilder sb = new StringBuilder();
  int n = 0;
  for (int i = 0; i < ds.size(); i++) {
    Object[] e = (Object[]) ds.get(i);
    if (r.drop((@PKG@.ZDep) e[0])) { sb.append((String) e[1]).append('\n'); n++; }
  }
  for (int i = 0; i < cs.size(); i++) {
    @PKG@.ZDep v = (@PKG@.ZDep) cs.get(i);
    if (r.check.remove(Long.valueOf(v.key), v)) sb.append(v.vline()).append('\n');
  }
  for (int i = 0; i < rs.size(); i++) {
    @PKG@.ZDep v = (@PKG@.ZDep) rs.get(i);
    if (r.recent.remove(Long.valueOf(v.key), v)) sb.append(v.vline()).append('\n');
  }
  r.snapshot(true);
  DROPPED.addAndGet((long) n);
  if (sb.length() > 0) @PKG@.ZCfg.info("zone reset (SkyyWorldGen): " + n + " waiting regrow block(s) in " + w + " forgotten without growing back (the land is regenerated; they are in the reset backup)");
  return sb.toString();
}""")
M(bx, r"""
public static int restore(String w, String text) {
  @PKG@.ZRw r = @PKG@.ZRegen.rw(w, true);
  if (r == null) return 0 - 1;
  if (text == null) return 0;
  String[] ls = text.split("\n");
  int n = 0;
  for (int i = 0; i < ls.length; i++) {
    String l = ls[i].trim();
    if (l.length() == 0 || l.startsWith("#")) continue;
    String[] a = l.split("\\s+");
    @PKG@.ZDep d = @PKG@.ZDep.parse(a);
    if (d == null) continue;
    Long k = Long.valueOf(d.key);
    if (a[0].equals("D")) {
      if (r.dep.putIfAbsent(k, d) != null) continue;
      if (!r.append(d.line())) { r.dep.remove(k, d); continue; }
      n++;
    } else if (r.check.putIfAbsent(k, d) == null) n++;
  }
  r.snapshot(true);
  RESTORED.addAndGet((long) n);
  if (n > 0) @PKG@.ZCfg.info("zone reset undo (SkyyWorldGen): " + n + " regrow entr(ies) of " + w + " put back from the reset backup");
  return n;
}""")
M(bx, r"""
public Object apply(Object o) {
  try {
    if (!(o instanceof Object[])) return null;
    Object[] a = (Object[]) o;
    if (a.length < 2 || !(a[0] instanceof String)) return null;
    String w = (String) a[0];
    if (this.mode == 0) {
      if (!(a[1] instanceof java.util.function.IntBinaryOperator)) return null;
      return drop(w, (java.util.function.IntBinaryOperator) a[1], a.length > 2 && a[2] instanceof String ? (String) a[2] : "");
    }
    if (!(a[1] instanceof String)) return null;
    return Integer.valueOf(restore(w, (String) a[1]));
  } catch (Throwable t) {
    @PKG@.ZCfg.warnOnce("zbox" + this.mode, "zone reset bridge (" + (this.mode == 0 ? "dropBox" : "restoreBox") + ") failed: " + t);
    return null;
  }
}""")

# =====================================================================================================================================
# ZFn: the bridge functions
# =====================================================================================================================================
''')
P.rep('''  b.put("zones:fn:check", CHECK);
  b.put("zones:fn:region", REGION);
''', '''  b.put("zones:fn:check", CHECK);
  b.put("zones:fn:region", REGION);
  @PKG@.ZBox.DROP = new @PKG@.ZBox(0);
  @PKG@.ZBox.BACK = new @PKG@.ZBox(1);
  b.put("zones:fn:dropBox", @PKG@.ZBox.DROP);         // 0.2.1 (SkyyWorldGen 0.7.10 zone reset)
  b.put("zones:fn:restoreBox", @PKG@.ZBox.BACK);      // 0.2.1 (its undo)
''')
P.rep('''    if (REGION != null) b.remove("zones:fn:region", REGION);
''', '''    if (REGION != null) b.remove("zones:fn:region", REGION);
    if (@PKG@.ZBox.DROP != null) b.remove("zones:fn:dropBox", @PKG@.ZBox.DROP);
    if (@PKG@.ZBox.BACK != null) b.remove("zones:fn:restoreBox", @PKG@.ZBox.BACK);
''')
P.rep('''ALL = [api, cfg, reg, idx, rules, sav, sto, eng, msg, bld, sel, wnd, dep, rw, pas, rgn, tkr, guard] + gcls + [shw, tick, fn, rkit, cmds] + vcls + [cmd, quit_, pl]
''', '''ALL = [api, cfg, reg, idx, rules, sav, sto, eng, msg, bld, sel, wnd, dep, rw, pas, rgn, tkr, guard] + gcls + [shw, tick, bx, fn, rkit, cmds] + vcls + [cmd, quit_, pl]
''')
assert P.s.count("registerSystem(") == SYS0 and P.s.count("registerCommand(") == CMD0, "0.2.1 adds no system / command"
P.finish()
